def countRotations(s, k):
    n = len(s)
    # Count equal neighbours around the whole circle (including the wrap-around pair)
    total = 0
    for i in range(n):
        if s[i] == s[(i + 1) % n]:
            total += 1

    count = 0
    # A rotation starting at index r cuts the circle between r - 1 and r
    for r in range(n):
        score = total
        # If the cut pair was equal, it no longer counts as adjacent
        if s[(r - 1) % n] == s[r]:
            score -= 1
        if score == k:
            count += 1
    return count
